      "gabarito": "Usar os dados efetivamente coletados, nunca preencher resultados esperados como se fossem observações. Conferir pergunta, população, categorias, frequências, título, escala, fonte e data. A chance teórica é 1/2; a frequência de caras depende do experimento e pode diferir de 50%. A síntese do gráfico da mídia deve respeitar os valores, o período e a população da fonte efetivamente consultada.",
