      "enunciado": "Reúna ou revise as produções abaixo. Numere os registros e explique as correções feitas após a devolutiva. Pesquisas e experimentos exigem dados realmente coletados; construções e algoritmos exigem os registros de execução. 1. Crie uma situação para C = 5n + 10. Faça uma tabela para três valores de n e transforme uma das linhas numa pergunta com incógnita. 2. Resolva 2(x + 4) = 26 por duas sequências de operações válidas e confira. 3. Crie um problema para 5x − 12 = 48. Defina x, resolva e explique como conferir no contexto. 4. Desenhe um padrão que comece com quatro peças e acrescente três por etapa. Dê a regra recursiva e uma expressão direta. Compare 3(n−1)+4 e 3n+1. 5. Resolva 12× 25 por dois algoritmos. Depois escreva e desenhe um fluxograma para calcular o total de n pacotes de 25; execute-o para n=4 e n=12.",
      "gabarito": "Conferência por tarefa: 1. Exemplo: taxa fixa de 10 e cinco por item. Para n=1,2,3, C=15,20,25. Perguntar a quantidade quando C=25 transforma n numa incógnita. 2. Dividir por 2 e subtrair 4 dá x=9. Outra estratégia: distribuir, obter 2x+8=26, subtrair 8 e dividir por 2. Ambas preservam a igualdade. 3. x=12. O enunciado deve representar cinco quantidades iguais, retirada de doze e resultado quarenta e oito; a substituição 5× 12−12=48 confirma. 4. Recursiva: iniciar com 4 e acrescentar 3. Direta: 4+3(n−1)=3n+1. As expressões são equivalentes pela distributiva. Relacionar a regra ao desenho de cada etapa. 5. 12× 25=300, por exemplo 10× 25+2× 25 ou 3×(4× 25). Fluxograma: ler n, multiplicar por 25, informar o total, terminar. Saídas 100 e 300.",
