          "titulo": "Produtos Notáveis",
          "enunciado": "Use um desenho de área para justificar(10+2)² e desenvolva(2x−1)². Explique a origem do termo do meio.",
          "gabarito": "144=100+20+20+4. (2x−1)²=4x²−4x+1; o termo do meio é a soma dos dois produtos−2x.",
          "bncc": [
            "EF09MA09"
          ],
          "atividadeOrigem": "mat.ef09.produtos_notaveis_fatoracao_e_equacoes_do_2_graus.produtos_notaveis#produtos_notaveis.investigacao"
