      "titulo": "Portfólio: Proporcionalidade e Juros",
      "enunciado": "Reúna ou revise as produções abaixo. Numere os registros e explique as correções feitas após a devolutiva. Pesquisas e experimentos exigem dados realmente coletados; construções e algoritmos exigem os registros de execução. 1. Uma máquina produz 100 peças por hora no modelo. Determine o tempo para 3.000 peças com três máquinas iguais e compare com duas máquinas. Escreva a relação entre peças, máquinas e tempo. 2. Desenhe três paralelas cortadas por duas secantes e proponha medidas coerentes para três intervalos conhecidos. Determine o quarto e explique a correspondência. 3. Crie um problema de ampliação com fator 3 e compare comprimentos, perímetros e áreas. Indique como provar que as figuras são semelhantes. 4. Compare numa planilha três períodos de 2% sobre 1.000 nos modelos simples e composto. Determine também a taxa total de uma mudança de 250 para 300. 5. Resolva um trajeto de 180 km em 3 h e compare com 90 km em 2 h. Explique a diferença entre razão global e velocidade em cada instante.",
      "gabarito": "Conferência por tarefa: 1. t=n/(100m). Para 3.000 peças:10 h com 3 máquinas e 15 h com 2. A hipótese de rendimento constante e trabalho simultâneo precisa ser indicada. 2. A equação deve comparar os mesmos intervalos entre paralelas. Verificar a igualdade das razões e indicar unidades, em vez de usar apenas a aparência do desenho. 3. Comprimentos e perímetros triplicam; áreas ficam nove vezes maiores. A semelhança exige mesma forma, ângulos correspondentes iguais e razão comum dos lados. 4. Simples:1.060. Composto:1.000× 1,02³=1.061,208, aproximadamente 1.061,21 ao final. A taxa de 250 para 300 é 50/250=20%. Explicitar arredondamento e base de cada etapa. 5. Médias 60 e 45 km/h. As médias comparam distância e tempo totais; sem outros dados, não determinam velocidades em trechos ou instantes.",
